(7502336, 1195554, 186753, '<td valign="top">Great subject matter, great moment for the challenge but the focus is soft and the image grainy. I don''t feel those things work together for an advantage here.</td>', 'Great subject matter, great moment for the challenge but the focus is soft and the image grainy. I don''t feel those things work together for an advantage here.', '2017-02-26 17:42:36.000000', NULL, 1),
(7502337, 1195702, 186753, '<td valign="top">Appropriately timed, a good moment to document in this generation regardless of which side of the debate you are on.The black and white makes it feel more like old time journalism and for me that makes the piece feel like it could have happened in any time period. I think it would have been stronger with a tighter landscape orientation crop here since we don''t need to devote so much space to the buildings, the story is the protest.</td>', 'Appropriately timed, a good moment to document in this generation regardless of which side of the debate you are on.The black and white makes it feel more like old time journalism and for me that makes the piece feel like it could have happened in any time period. I think it would have been stronger with a tighter landscape orientation crop here since we don''t need to devote so much space to the buildings, the story is the protest.', '2017-02-26 17:45:58.000000', NULL, 1),
(7502338, 1195671, 186753, '<td valign="top">Very strong image and good aesthetic treatment.</td>', 'Very strong image and good aesthetic treatment.', '2017-02-26 17:47:26.000000', NULL, 1),
